//! ↩️ move-buffer leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfBuffer;
use crate::artifacts::gltf::schema::mutations::move_buffer::mutation::{validate, GltfMoveBufferPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{buffers_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.move-buffer.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfMoveBufferInverseOperation { Insert { position: usize, item: GltfBuffer, bytes: Vec<u8> }, Delete { index: usize, removed: GltfBuffer, bytes: Vec<u8> }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfMoveBufferInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfMoveBufferPayload, pub operation: GltfMoveBufferInverseOperation }
async fn operation(payload: &GltfMoveBufferPayload, base: &GltfSnapshot) -> GltfMoveBufferInverseOperation { GltfMoveBufferInverseOperation::Move { index: payload.position, position: payload.index } }
async fn touched_paths(payload: &GltfMoveBufferPayload) -> Vec<String> { vec![format!("document/buffers/{}", payload.index), format!("document/buffers/{}", payload.position), format!("buffers/{}", payload.index), format!("buffers/{}", payload.position)] }
pub async fn validate_inverse(inverse: &GltfMoveBufferInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub async fn apply_inverse(inverse: &GltfMoveBufferInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfMoveBufferInverseOperation::Insert { position, .. } if *position > after.document.buffers.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/buffers", "position must be within the collection")), GltfMoveBufferInverseOperation::Delete { index, .. } if *index >= after.document.buffers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/buffers", "index must address an item")), GltfMoveBufferInverseOperation::Move { index, position } if *index >= after.document.buffers.len() || *position >= after.document.buffers.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/buffers", "indices must address items")), GltfMoveBufferInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.buffers.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.buffers.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/buffers", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfMoveBufferInverseOperation::Insert { position, item, bytes } => { repair(&mut next.document, GltfTopLevelFamily::Buffers, &Change::Insert(*position))?; next.document.buffers.insert(*position, item.clone()); next.buffers.insert(*position, bytes.clone()); }, GltfMoveBufferInverseOperation::Delete { index, .. } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, *index, None, None)?; next.buffers.remove(*index); }, GltfMoveBufferInverseOperation::Move { index, position } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, *index, Some(*position), None)?; let bytes = next.buffers.remove(*index); next.buffers.insert(*position, bytes); }, GltfMoveBufferInverseOperation::Reorder { order } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, order[0], None, Some(order))?; next.buffers = order.iter().map(|index| next.buffers[*index].clone()).collect(); } } Ok(next) }
pub async fn encode(inverse: &GltfMoveBufferInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub async fn derive(payload: &GltfMoveBufferPayload, base: &GltfSnapshot) -> Result<GltfMoveBufferInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfMoveBufferInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
